addedDeclarations.type:
∀ {D : Type u_1} {E : Type u_2} [inst : NormedAddCommGroup D] [inst_1 : NormedSpace ℂ D] [inst_2 : NormedAddCommGroup E]
  [inst_3 : InnerProductSpace ℂ E] [Nontrivial E] (j : D →L[ℂ] E) (hj : Function.Bijective ⇑j),
  (Adiabatic.Foundations.doubledDomain j hj).spectrum (Adiabatic.Foundations.doubledHamiltonian j) = {1, -1}

strictDeclarations.type:
∀ {R : Type u_1} {D : Type u_2} {E : Type u_3} [inst : Semiring R] [inst_1 : AddCommMonoid D] [inst_2 : AddCommMonoid E]
  [inst_3 : _root_.Module R D] [inst_4 : _root_.Module R E] {A : D →ₗ[R] E}
  (r : Adiabatic.ChoiceReduction.ExplicitLinearInverse A) (x : E), A (r.inverse x) = x

∀ {R : Type u_1} {D : Type u_2} {E : Type u_3} [inst : Semiring R] [inst_1 : AddCommMonoid D] [inst_2 : AddCommMonoid E]
  [inst_3 : _root_.Module R D] [inst_4 : _root_.Module R E] {A : D →ₗ[R] E}
  (r : Adiabatic.ChoiceReduction.ExplicitLinearInverse A) (x : D), r.inverse (A x) = x

∀ {R : Type u_1} {D : Type u_2} {E : Type u_3} [inst : Semiring R] [inst_1 : AddCommMonoid D] [inst_2 : AddCommMonoid E]
  [inst_3 : _root_.Module R D] [inst_4 : _root_.Module R E] {A : D →ₗ[R] E}
  (self : Adiabatic.ChoiceReduction.ExplicitLinearInverse A), self.inverse ∘ₗ A = LinearMap.id

∀ {R : Type u_1} {D : Type u_2} {E : Type u_3} {inst : Semiring R} {inst_1 : AddCommMonoid D} {inst_2 : AddCommMonoid E}
  {inst_3 : _root_.Module R D} {inst_4 : _root_.Module R E} {A : D →ₗ[R] E} {inverse : E →ₗ[R] D}
  {left_inverse : inverse ∘ₗ A = LinearMap.id} {right_inverse : A ∘ₗ inverse = LinearMap.id} {inverse_1 : E →ₗ[R] D}
  {left_inverse_1 : inverse_1 ∘ₗ A = LinearMap.id} {right_inverse_1 : A ∘ₗ inverse_1 = LinearMap.id},
  { inverse := inverse, left_inverse := left_inverse, right_inverse := right_inverse } =
      { inverse := inverse_1, left_inverse := left_inverse_1, right_inverse := right_inverse_1 } →
    inverse = inverse_1

∀ {R : Type u_1} {D : Type u_2} {E : Type u_3} [inst : Semiring R] [inst_1 : AddCommMonoid D] [inst_2 : AddCommMonoid E]
  [inst_3 : _root_.Module R D] [inst_4 : _root_.Module R E] {A : D →ₗ[R] E}
  (r s : Adiabatic.ChoiceReduction.ExplicitLinearInverse A) (x : E), r.inverse x = s.inverse x

∀ {R : Type u_1} {D : Type u_2} {E : Type u_3} [inst : Semiring R] [inst_1 : AddCommMonoid D] [inst_2 : AddCommMonoid E]
  [inst_3 : _root_.Module R D] [inst_4 : _root_.Module R E] {A : D →ₗ[R] E}
  (self : Adiabatic.ChoiceReduction.ExplicitLinearInverse A), A ∘ₗ self.inverse = LinearMap.id

∀ {A : Type u_1} {B : Type u_2} {M : Type u_3} {inst : Monoid A} {inst_1 : Monoid B} {inst_2 : AddCommGroup M}
  {left : A → M → M} {right : M → B → M} {left_one : ∀ (x : M), left 1 x = x} {right_one : ∀ (x : M), right x 1 = x}
  {left_mul : ∀ (a b : A) (x : M), left (a * b) x = left a (left b x)}
  {right_mul : ∀ (x : M) (a b : B), right x (a * b) = right (right x a) b}
  {left_right : ∀ (a : A) (x : M) (b : B), left a (right x b) = right (left a x) b}
  {left_add : ∀ (a : A) (x y : M), left a (x + y) = left a x + left a y}
  {right_add : ∀ (x y : M) (b : B), right (x + y) b = right x b + right y b} {left_1 : A → M → M} {right_1 : M → B → M}
  {left_one_1 : ∀ (x : M), left_1 1 x = x} {right_one_1 : ∀ (x : M), right_1 x 1 = x}
  {left_mul_1 : ∀ (a b : A) (x : M), left_1 (a * b) x = left_1 a (left_1 b x)}
  {right_mul_1 : ∀ (x : M) (a b : B), right_1 x (a * b) = right_1 (right_1 x a) b}
  {left_right_1 : ∀ (a : A) (x : M) (b : B), left_1 a (right_1 x b) = right_1 (left_1 a x) b}
  {left_add_1 : ∀ (a : A) (x y : M), left_1 a (x + y) = left_1 a x + left_1 a y}
  {right_add_1 : ∀ (x y : M) (b : B), right_1 (x + y) b = right_1 x b + right_1 y b},
  { left := left, right := right, left_one := left_one, right_one := right_one, left_mul := left_mul,
        right_mul := right_mul, left_right := left_right, left_add := left_add, right_add := right_add } =
      { left := left_1, right := right_1, left_one := left_one_1, right_one := right_one_1, left_mul := left_mul_1,
        right_mul := right_mul_1, left_right := left_right_1, left_add := left_add_1, right_add := right_add_1 } →
    left = left_1 ∧ right = right_1

∀ {A : Type u_1} {B : Type u_2} {M : Type u_3} {R : Type u_4} [inst : Ring A] [inst_1 : Ring B]
  [inst_2 : AddCommGroup M] [inst_3 : Semiring R] [inst_4 : PartialOrder R]
  {act : Adiabatic.ChoiceReduction.MixedAction A B M} {physical : Adiabatic.ChoiceReduction.SubmultiplicativeSize A R}
  {domain : Adiabatic.ChoiceReduction.SubmultiplicativeSize B R}
  (self : Adiabatic.ChoiceReduction.MixedSize act physical domain) (x y : M),
  self.size (x + y) ≤ self.size x + self.size y

∀ {A : Type u_1} {B : Type u_2} {M : Type u_3} {R : Type u_4} [inst : Ring A] [inst_1 : Ring B]
  [inst_2 : AddCommGroup M] [inst_3 : Semiring R] [inst_4 : PartialOrder R]
  {act : Adiabatic.ChoiceReduction.MixedAction A B M} {physical : Adiabatic.ChoiceReduction.SubmultiplicativeSize A R}
  {domain : Adiabatic.ChoiceReduction.SubmultiplicativeSize B R}
  (self : Adiabatic.ChoiceReduction.MixedSize act physical domain) (a : A) (x : M),
  self.size (act.left a x) ≤ physical.size a * self.size x

∀ {A : Type u_1} {B : Type u_2} {M : Type u_3} {R : Type u_4} {inst : Ring A} {inst_1 : Ring B}
  {inst_2 : AddCommGroup M} {inst_3 : Semiring R} {inst_4 : PartialOrder R}
  {act : Adiabatic.ChoiceReduction.MixedAction A B M} {physical : Adiabatic.ChoiceReduction.SubmultiplicativeSize A R}
  {domain : Adiabatic.ChoiceReduction.SubmultiplicativeSize B R} {size : M → R} {nonneg : ∀ (x : M), 0 ≤ size x}
  {zero : size 0 = 0} {add : ∀ (x y : M), size (x + y) ≤ size x + size y}
  {left : ∀ (a : A) (x : M), size (act.left a x) ≤ physical.size a * size x}
  {right : ∀ (x : M) (b : B), size (act.right x b) ≤ size x * domain.size b} {size_1 : M → R}
  {nonneg_1 : ∀ (x : M), 0 ≤ size_1 x} {zero_1 : size_1 0 = 0}
  {add_1 : ∀ (x y : M), size_1 (x + y) ≤ size_1 x + size_1 y}
  {left_1 : ∀ (a : A) (x : M), size_1 (act.left a x) ≤ physical.size a * size_1 x}
  {right_1 : ∀ (x : M) (b : B), size_1 (act.right x b) ≤ size_1 x * domain.size b},
  { size := size, nonneg := nonneg, zero := zero, add := add, left := left, right := right } =
      { size := size_1, nonneg := nonneg_1, zero := zero_1, add := add_1, left := left_1, right := right_1 } →
    size = size_1

∀ {A : Type u_1} {B : Type u_2} {M : Type u_3} {R : Type u_4} [inst : Ring A] [inst_1 : Ring B]
  [inst_2 : AddCommGroup M] [inst_3 : Semiring R] [inst_4 : PartialOrder R]
  {act : Adiabatic.ChoiceReduction.MixedAction A B M} {physical : Adiabatic.ChoiceReduction.SubmultiplicativeSize A R}
  {domain : Adiabatic.ChoiceReduction.SubmultiplicativeSize B R}
  (self : Adiabatic.ChoiceReduction.MixedSize act physical domain) (x : M), 0 ≤ self.size x

∀ {A : Type u_1} {B : Type u_2} {M : Type u_3} {R : Type u_4} [inst : Ring A] [inst_1 : Ring B]
  [inst_2 : AddCommGroup M] [inst_3 : Semiring R] [inst_4 : PartialOrder R]
  {act : Adiabatic.ChoiceReduction.MixedAction A B M} {physical : Adiabatic.ChoiceReduction.SubmultiplicativeSize A R}
  {domain : Adiabatic.ChoiceReduction.SubmultiplicativeSize B R}
  (self : Adiabatic.ChoiceReduction.MixedSize act physical domain) (x : M) (b : B),
  self.size (act.right x b) ≤ self.size x * domain.size b

∀ {A : Type u_1} {B : Type u_2} {M : Type u_3} {R : Type u_4} [inst : Ring A] [inst_1 : Ring B]
  [inst_2 : AddCommGroup M] [inst_3 : Semiring R] [inst_4 : PartialOrder R]
  {act : Adiabatic.ChoiceReduction.MixedAction A B M} {physical : Adiabatic.ChoiceReduction.SubmultiplicativeSize A R}
  {domain : Adiabatic.ChoiceReduction.SubmultiplicativeSize B R}
  (self : Adiabatic.ChoiceReduction.MixedSize act physical domain), self.size 0 = 0

∀ {A : Type u_1} {R : Type u_2} {inst : Ring A} {inst_1 : Semiring R} {inst_2 : PartialOrder R} {size : A → R}
  {nonneg : ∀ (a : A), 0 ≤ size a} {zero : size 0 = 0} {one : size 1 ≤ 1}
  {add : ∀ (a b : A), size (a + b) ≤ size a + size b} {mul : ∀ (a b : A), size (a * b) ≤ size a * size b}
  {size_1 : A → R} {nonneg_1 : ∀ (a : A), 0 ≤ size_1 a} {zero_1 : size_1 0 = 0} {one_1 : size_1 1 ≤ 1}
  {add_1 : ∀ (a b : A), size_1 (a + b) ≤ size_1 a + size_1 b}
  {mul_1 : ∀ (a b : A), size_1 (a * b) ≤ size_1 a * size_1 b},
  { size := size, nonneg := nonneg, zero := zero, one := one, add := add, mul := mul } =
      { size := size_1, nonneg := nonneg_1, zero := zero_1, one := one_1, add := add_1, mul := mul_1 } →
    size = size_1
